/**
 * A row whose items wrap onto further lines, laid out as Compose's FlowRow, on stable API only (§14.40): one AAR
 * runs on Compose BOM 2024.12.01 and 2026.08.00. [horizontalArrangement] places each line within the row's width,
 * [verticalArrangement] the lines; [content] has RowScope's weight, align, alignBy and alignByBaseline.
 */
@Composable
internal fun SbFlowRow(
    modifier: Modifier = Modifier,
    horizontalArrangement: Arrangement.Horizontal = Arrangement.Start,
    verticalArrangement: Arrangement.Vertical = Arrangement.Top,
    content: @Composable RowScope.() -> Unit,
) {
    val policy = remember(horizontalArrangement, verticalArrangement) {
        SbFlowMeasurePolicy(horizontalArrangement, verticalArrangement)
    }
    Layout(content = { SbFlowRowScope.content() }, modifier = modifier, measurePolicy = policy)
}

/** What an item's RowScope modifiers say: its weight, its own vertical alignment or the line it aligns by. */
private class SbFlowItem {
    var weight = 0f
    var fill = true
    var align: Alignment.Vertical? = null
    var alignBy: ((Measured) -> Int)? = null
}

private data class SbFlowItemElement(
    val weight: Float = 0f,
    val fill: Boolean = true,
    val align: Alignment.Vertical? = null,
    val line: HorizontalAlignmentLine? = null,
    val by: ((Measured) -> Int)? = null,
) : ModifierNodeElement<SbFlowItemNode>() {
    override fun create() = SbFlowItemNode(this)
    override fun update(node: SbFlowItemNode) {
        node.element = this
    }
}

private class SbFlowItemNode(var element: SbFlowItemElement) : Modifier.Node(), ParentDataModifierNode {
    override fun Density.modifyParentData(parentData: Any?): Any = ((parentData as? SbFlowItem) ?: SbFlowItem()).also {
        val e = element
        if (e.weight > 0f) {
            it.weight = e.weight
            it.fill = e.fill
        }
        if (e.align != null) it.align = e.align
        if (e.line != null) it.alignBy = { m -> m[e.line] }
        if (e.by != null) it.alignBy = e.by
    }
}

private object SbFlowRowScope : RowScope {
    override fun Modifier.weight(weight: Float, fill: Boolean): Modifier {
        require(weight > 0f) { "weight must be positive, was $weight" }
        return this.then(SbFlowItemElement(weight = weight, fill = fill))
    }

    override fun Modifier.align(alignment: Alignment.Vertical): Modifier = this.then(SbFlowItemElement(align = alignment))

    override fun Modifier.alignBy(alignmentLine: HorizontalAlignmentLine): Modifier =
        this.then(SbFlowItemElement(line = alignmentLine))

    override fun Modifier.alignByBaseline(): Modifier = alignBy(FirstBaseline)

    override fun Modifier.alignBy(alignmentLineBlock: (Measured) -> Int): Modifier =
        this.then(SbFlowItemElement(by = alignmentLineBlock))
}

private val Measurable.sbFlowItem: SbFlowItem? get() = parentData as? SbFlowItem

private class SbFlowMeasurePolicy(
    private val horizontal: Arrangement.Horizontal,
    private val vertical: Arrangement.Vertical,
) : MeasurePolicy {
    override fun MeasureScope.measure(measurables: List<Measurable>, constraints: Constraints): MeasureResult {
        // FlowRow's height overflow (Clip, its default in foundation-layout 1.7.6, as 1.12.0): no height, no items
        if (measurables.isEmpty() || constraints.maxHeight == 0) return layout(0, 0) {}
        val maxWidth = constraints.maxWidth
        val bounded = constraints.hasBoundedWidth
        val hGap = horizontal.spacing.roundToPx()
        val vGap = vertical.spacing.roundToPx()
        val loose = Constraints(maxWidth = maxWidth, maxHeight = constraints.maxHeight)
        val n = measurables.size
        val placeables = arrayOfNulls<Placeable>(n)
        // break into lines as FlowRow: an item breaks by its measured size, or (with a weight) by its minimum intrinsic
        // width and the minimum intrinsic height there; the first item whose height does not fit into what the lines
        // above leave of the row's height stays out, and so does every item after it (FlowRow's Clip)
        val lines = mutableListOf<IntRange>()
        val lineUsed = mutableListOf<Int>()
        var start = 0
        var used = 0
        var lineCross = 0
        var crossLeft = constraints.maxHeight
        var shown = 0
        for (i in 0 until n) {
            val m = measurables[i]
            val main: Int
            val cross: Int
            if ((m.sbFlowItem?.weight ?: 0f) > 0f) {
                main = m.minIntrinsicWidth(Constraints.Infinity)
                cross = m.minIntrinsicHeight(main)
            } else {
                val p = m.measure(loose).also { placeables[i] = it }
                main = p.measuredWidth
                cross = p.measuredHeight
            }
            if (i > start && bounded && used + hGap + main > maxWidth) {
                lines += start until i
                lineUsed += used
                crossLeft -= lineCross + vGap
                start = i
                lineCross = 0
            }
            if (cross > crossLeft) break
            used = if (i == start) main else used + hGap + main
            lineCross = max(lineCross, cross)
            shown = i + 1
        }
        if (shown > start) {
            lines += start until shown
            lineUsed += used
        }
        // weights share what is left of their line, rounded as in a Row (an unbounded row: what the line used)
        var width = 0
        lines.forEachIndexed { l, line ->
            val weighted = line.filter { placeables[it] == null }
            val gaps = hGap * (line.count() - 1)
            if (weighted.isNotEmpty()) {
                val fixed = line.filter { placeables[it] != null }.sumOf { placeables[it]!!.measuredWidth }
                val total = weighted.sumOf { measurables[it].sbFlowItem!!.weight.toDouble() }.toFloat()
                val remaining = (if (bounded) maxWidth else lineUsed[l]) - fixed - gaps
                val unit = remaining / total
                var remainder = remaining - weighted.sumOf { (unit * measurables[it].sbFlowItem!!.weight).roundToInt() }
                for (i in weighted) {
                    val item = measurables[i].sbFlowItem!!
                    val step = remainder.coerceIn(-1, 1)
                    remainder -= step
                    val share = max(0, (unit * item.weight).roundToInt() + step)
                    placeables[i] = measurables[i].measure(
                        Constraints(minWidth = if (item.fill) share else 0, maxWidth = share, maxHeight = constraints.maxHeight)
                    )
                }
            }
            width = max(width, line.sumOf { placeables[it]!!.measuredWidth } + gaps)
        }
        // as FlowRow, the lines are arranged within the widest line, even where an item wider than the row (a
        // requiredWidth) makes it wider than the row's own width
        val lineSpace = max(width, constraints.minWidth)
        width = width.coerceIn(constraints.minWidth, maxWidth)
        // line heights: the tallest item, or what the items aligned by a line need above and below it
        val before = IntArray(n)
        val lineHeights = IntArray(lines.size)
        val lineBefore = IntArray(lines.size)
        lines.forEachIndexed { l, line ->
            var tallest = 0
            var above = 0
            var below = 0
            for (i in line) {
                val p = placeables[i]!!
                val by = measurables[i].sbFlowItem?.alignBy
                val b = by?.invoke(p)?.takeIf { it != AlignmentLine.Unspecified }
                if (b != null) {
                    before[i] = b
                    above = max(above, b)
                    below = max(below, p.height - b)
                } else {
                    before[i] = AlignmentLine.Unspecified
                    tallest = max(tallest, p.height)
                }
            }
            lineHeights[l] = max(tallest, above + below)
            lineBefore[l] = above
        }
        val content = lineHeights.sum() + vGap * max(0, lines.size - 1)
        val height = content.coerceIn(constraints.minHeight, constraints.maxHeight)
        val lineY = IntArray(lines.size)
        with(vertical) { arrange(height, lineHeights, lineY) }
        return layout(width, height) {
            lines.forEachIndexed { l, line ->
                val sizes = IntArray(line.count()) { k -> placeables[line.first + k]!!.measuredWidth }
                val xs = IntArray(sizes.size)
                with(horizontal) { arrange(lineSpace, sizes, layoutDirection, xs) }
                for ((k, i) in line.withIndex()) {
                    val p = placeables[i]!!
                    val align = measurables[i].sbFlowItem?.align
                    val dy = when {
                        before[i] != AlignmentLine.Unspecified -> lineBefore[l] - before[i]
                        align != null -> align.align(p.height, lineHeights[l])
                        else -> 0
                    }
                    p.place(xs[k], lineY[l] + dy)
                }
            }
        }
    }

    /**
     * FlowRow's minimum intrinsic width: the narrowest width (a binary search between the widest item and one line)
     * whose lines fit into [height], each item at its minimum intrinsic width and the minimum intrinsic height there;
     * as FlowRow, the search stops at the first width whose lines are exactly [height] high, and returns one more than
     * one line when no width fits.
     */
    override fun IntrinsicMeasureScope.minIntrinsicWidth(measurables: List<IntrinsicMeasurable>, height: Int): Int {
        if (measurables.isEmpty()) return 0
        val mains = IntArray(measurables.size) { measurables[it].minIntrinsicWidth(height) }
        val crosses = IntArray(measurables.size) { measurables[it].minIntrinsicHeight(mains[it]) }
        var low = mains.max()
        var high = mains.sum() + horizontal.spacing.roundToPx() * (measurables.size - 1)
        var width = high
        var used = linesHeight(mains, crosses, width)
        while (low <= high) {
            if (used == height) return width
            width = (low + high) / 2
            used = linesHeight(mains, crosses, width)
            when {
                used > height -> {
                    low = width + 1
                    if (low > high) return low
                }
                used < height -> high = width - 1
                else -> return width
            }
        }
        return width
    }

    override fun IntrinsicMeasureScope.maxIntrinsicWidth(measurables: List<IntrinsicMeasurable>, height: Int): Int =
        measurables.sumOf { it.maxIntrinsicWidth(height) } + horizontal.spacing.roundToPx() * max(0, measurables.size - 1)

    override fun IntrinsicMeasureScope.minIntrinsicHeight(measurables: List<IntrinsicMeasurable>, width: Int): Int =
        intrinsicHeight(measurables, width)

    /** FlowRow gives its minimum intrinsic height here too. */
    override fun IntrinsicMeasureScope.maxIntrinsicHeight(measurables: List<IntrinsicMeasurable>, width: Int): Int =
        intrinsicHeight(measurables, width)

    /**
     * FlowRow's intrinsic height at [width]: the items break into lines by their minimum intrinsic width (weight or
     * not), each line as high as its tallest item's minimum intrinsic height at the whole [width].
     */
    private fun IntrinsicMeasureScope.intrinsicHeight(measurables: List<IntrinsicMeasurable>, width: Int): Int =
        linesHeight(
            IntArray(measurables.size) { measurables[it].minIntrinsicWidth(Constraints.Infinity) },
            IntArray(measurables.size) { measurables[it].minIntrinsicHeight(width) },
            width,
        )

    /** The height of the lines items of these widths and heights make in [width], with the vertical spacing. */
    private fun IntrinsicMeasureScope.linesHeight(mains: IntArray, crosses: IntArray, width: Int): Int {
        if (mains.isEmpty()) return 0
        val hGap = horizontal.spacing.roundToPx()
        var total = 0
        var lines = 1
        var used = mains[0]
        var lineHeight = crosses[0]
        for (i in 1 until mains.size) {
            if (width != Constraints.Infinity && used + hGap + mains[i] > width) {
                total += lineHeight
                lines++
                used = mains[i]
                lineHeight = crosses[i]
            } else {
                used += hGap + mains[i]
                lineHeight = max(lineHeight, crosses[i])
            }
        }
        return total + lineHeight + vertical.spacing.roundToPx() * (lines - 1)
    }
}
